<section class="admin-toolbar">
    <form method="get" action="<?= e(url('/admin/' . $resource)) ?>"><label><span class="sr-only">بحث</span><input type="search" name="q" value="<?= e($q) ?>" placeholder="بحث في <?= e($resourceConfig['label']) ?>..."></label><?php if (isset($resourceConfig['fields']['status'])): ?><select name="status"><option value="">كل الحالات</option><option value="published" <?= $status === 'published' ? 'selected' : '' ?>>منشور</option><option value="draft" <?= $status === 'draft' ? 'selected' : '' ?>>مسودة</option><option value="hidden" <?= $status === 'hidden' ? 'selected' : '' ?>>مخفي</option></select><?php endif; ?><button type="submit">تصفية</button></form>
    <?php if (!($resourceConfig['no_create'] ?? false) && !($resourceConfig['read_only'] ?? false) && $resource !== 'media'): ?><a class="admin-primary" href="<?= e(url('/admin/' . $resource . '/create')) ?>">إضافة جديد <span>＋</span></a><?php endif; ?>
</section>
<?php if ($resource === 'media'): ?>
<form class="upload-panel" method="post" action="<?= e(url('/admin/media/upload')) ?>" enctype="multipart/form-data"><?= csrf_field() ?><label><span>اختر صورة أو PDF (حتى <?= e(env('UPLOAD_MAX_MB', 8)) ?>MB)</span><input type="file" name="file" accept="image/jpeg,image/png,image/webp,application/pdf" required></label><label><span>النص البديل العربي</span><input type="text" name="alt_ar" maxlength="255"></label><label><span>النص البديل الإنجليزي</span><input type="text" name="alt_en" maxlength="255" dir="ltr"></label><button type="submit">رفع الملف</button></form>
<?php endif; ?>
<section class="admin-table-card">
    <div class="admin-table-scroll"><table><thead><tr><th>#</th><th>العنوان / المرجع</th><?php if (isset($resourceConfig['fields']['status'])): ?><th>الحالة</th><?php endif; ?><th>آخر تحديث</th><th>الإجراءات</th></tr></thead><tbody>
        <?php foreach ($items as $item): ?><tr><td><?= e($item['id']) ?></td><td><strong><?= e($item[$resourceConfig['title']] ?? ('#' . $item['id'])) ?></strong><?php if ($resource === 'contact_messages'): ?><small><?= e($item['email']) ?></small><?php elseif ($resource === 'media'): ?><small dir="ltr">/media/<?= e($item['id']) ?></small><?php elseif (!empty($item['title_en'])): ?><small dir="ltr"><?= e($item['title_en']) ?></small><?php endif; ?></td><?php if (isset($resourceConfig['fields']['status'])): ?><td><span class="status-pill <?= e($item['status']) ?>"><?= match($item['status']) { 'published' => 'منشور', 'draft' => 'مسودة', 'hidden' => 'مخفي', 'new' => 'جديدة', 'read' => 'مقروءة', 'archived' => 'مؤرشفة', default => e($item['status']) } ?></span></td><?php endif; ?><td dir="ltr"><?= e($item['updated_at'] ?? $item['created_at'] ?? '') ?></td><td><div class="table-actions">
            <?php if (!($resourceConfig['read_only'] ?? false)): ?><a href="<?= e(url('/admin/' . $resource . '/' . $item['id'] . '/edit')) ?>">تعديل</a><?php endif; ?>
            <?php if (!in_array($resource, ['settings', 'users', 'contact_messages', 'activity_logs'], true)): ?><a href="<?= e(url('/admin/' . $resource . '/' . $item['id'] . '/preview')) ?>" target="_blank" rel="noopener">معاينة</a><?php endif; ?>
            <?php if ($resource === 'media'): ?><a href="<?= e(url('/admin/media/file/' . $item['id'])) ?>" target="_blank" rel="noopener">فتح الملف</a><?php endif; ?>
            <?php if (!($resourceConfig['read_only'] ?? false) && isset($resourceConfig['fields']['status']) && !in_array($resource, ['contact_messages'], true)): ?><form method="post" action="<?= e(url('/admin/' . $resource . '/' . $item['id'] . '/toggle')) ?>"><?= csrf_field() ?><button type="submit"><?= $item['status'] === 'published' ? 'إخفاء' : 'نشر' ?></button></form><?php endif; ?>
            <?php if (!($resourceConfig['read_only'] ?? false) && $resource !== 'settings'): ?><form method="post" action="<?= e(url('/admin/' . $resource . '/' . $item['id'] . '/delete')) ?>" data-confirm="هل تريد حذف هذا العنصر؟"><?= csrf_field() ?><button class="danger" type="submit">حذف</button></form><?php endif; ?>
        </div></td></tr><?php endforeach; ?>
        <?php if (!$items): ?><tr><td colspan="5"><div class="empty-state">لا توجد عناصر مطابقة حالياً.</div></td></tr><?php endif; ?>
    </tbody></table></div>
    <?php if ($pages > 1): ?><nav class="pagination" aria-label="الصفحات"><?php for ($i = 1; $i <= $pages; $i++): ?><a class="<?= $i === $page ? 'active' : '' ?>" href="<?= e(url('/admin/' . $resource . '?page=' . $i . '&q=' . rawurlencode($q) . '&status=' . rawurlencode($status))) ?>"><?= e($i) ?></a><?php endfor; ?></nav><?php endif; ?>
</section>
